    /// A noun form.
    pub fn noun_scored(&self, word: &str, definiteness: Definiteness, case: Case, number: Number) -> Scored<String> {
        let cell: Option<u32> = match (definiteness, case, number,) {
            (Definiteness::Indefinite, Case::Nominative, Number::Singular,) => Some(0),
            (Definiteness::Indefinite, Case::Nominative, Number::Plural,) => Some(1),
            (Definiteness::Indefinite, Case::Genitive, Number::Singular,) => Some(2),
            (Definiteness::Indefinite, Case::Genitive, Number::Plural,) => Some(3),
            (Definiteness::Definite, Case::Nominative, Number::Singular,) => Some(4),
            (Definiteness::Definite, Case::Nominative, Number::Plural,) => Some(5),
            (Definiteness::Definite, Case::Genitive, Number::Singular,) => Some(6),
            (Definiteness::Definite, Case::Genitive, Number::Plural,) => Some(7),
        };
        match (model(), cell) {
            (Some(m), Some(c)) => m.inflect(0, c, word, self.options),
            _ => Vec::new(),
        }
    }

    /// A noun form. The best candidate; the word itself if nothing is known.
    pub fn noun(&self, word: &str, definiteness: Definiteness, case: Case, number: Number) -> String {
        best(self.noun_scored(word, definiteness, case, number), word)
    }

    /// Scored gender of a noun.
    pub fn noun_gender(&self, word: &str) -> Scored<Gender> {
        model().map(|m| m.inherent(0, 0, word).into_iter().filter_map(|(v, p)| Some((Gender::ALL.get(v as usize).copied()?, p))).collect()).unwrap_or_default()
    }

